  "fuel_firewood",
  "material_lumber",
]));

const CAMPFIRE_METAL_MATERIALS = Object.freeze(new Set([
  "metal",
  "iron",
  "steel",
  "bronze",
  "silver",
  "gold",
  "copper",
  "lead",
]));

/**
